`,Mvt=Object.freeze(Object.defineProperty({__proto__:null,attributes:zvt,html:Xvt},Symbol.toStringTag,{value:"Module"})),qvt={title:"Surrealist 3.1.5",date:"2024/12/05"},Vvt=`<ul>
