`,Jvt=Object.freeze(Object.defineProperty({__proto__:null,attributes:Hvt,html:Kvt},Symbol.toStringTag,{value:"Module"})),ebt={title:"Surrealist 3.1.9",date:"2024/12/24"},tbt=`<ul>
