`,dbt=Object.freeze(Object.defineProperty({__proto__:null,attributes:cbt,html:ubt},Symbol.toStringTag,{value:"Module"})),fbt={title:"Surrealist 3.2.3",date:"2025/02/21"},hbt=`<ul>
