`,pbt=Object.freeze(Object.defineProperty({__proto__:null,attributes:fbt,html:hbt},Symbol.toStringTag,{value:"Module"})),Obt={title:"Surrealist 3.2.4",date:"2025/02/21"},mbt=`<ul>
