`,Mbt=Object.freeze(Object.defineProperty({__proto__:null,attributes:zbt,html:Xbt},Symbol.toStringTag,{value:"Module"})),qbt={title:"Surrealist 3.4.2",date:"2025/06/27"},Vbt=`<ul>
