`,Ubt=Object.freeze(Object.defineProperty({__proto__:null,attributes:qbt,html:Vbt},Symbol.toStringTag,{value:"Module"})),Fbt={title:"Surrealist 3.4.3",date:"2025/07/02"},Wbt=`<ul>
