`,Ybt=Object.freeze(Object.defineProperty({__proto__:null,attributes:Fbt,html:Wbt},Symbol.toStringTag,{value:"Module"})),Gbt={title:"Surrealist 3.4.4",date:"2025/07/07"},Zbt=`<ul>
